/* @autogenerated */
import { BulkEditField } from 'app/shared/toolkit/bulk-edit/bulk-edit.model';
import { BaseBulkEditAction } from 'app/shared/toolkit/action/base-bulk-edit-action';
import { ObservedEmbedRepository } from 'app/features/observe/observed-embed/repository/observed-embed-repository.service';
import { ObservedEmbed } from 'app/features/observe/observed-embed/model/observed-embed.model';
import { BulkEditDialogData } from 'app/shared/toolkit/bulk-edit/bulk-edit-dialog.component';
import { Component, inject } from '@angular/core';

/** Edición masiva de observed embed: los campos que se pueden cambiar en bloque. */
@Component({ selector: 'observed-embed-view-bulk-edit-action', standalone: false, template: '' })
export class ObservedEmbedViewBulkEditActionComponent extends BaseBulkEditAction<ObservedEmbed> {
  readonly name = 'bulkEdit';
  protected readonly scope = 'observe/observed-embed';
  protected readonly repository = inject(ObservedEmbedRepository);

  protected override keyOf(item: ObservedEmbed): string {
    return String(item.uid);
  }

  /** Los campos que se pueden editar en bloque y el tipo de cada uno. */
  protected bulkFields(): readonly BulkEditField<ObservedEmbed>[] {
    return [
      { name: 'name', label: this.text('fieldName'), type: 'text' },
      { name: 'panelUid', label: this.text('fieldPanelUid'), type: 'text', optional: true },
      { name: 'origin', label: this.text('fieldOrigin'), type: 'relation', optional: true },
      { name: 'allowedOrigins', label: this.text('fieldAllowedOrigins'), type: 'text' },
      {
        name: 'maxRange',
        label: this.text('fieldMaxRange'),
        type: 'enum',
        options: [
          { value: 'hour', label: 'hour' },
          { value: 'six-hours', label: 'six-hours' },
          { value: 'day', label: 'day' },
          { value: 'week', label: 'week' },
          { value: 'month', label: 'month' },
        ],
      },
      { name: 'minRefresh', label: this.text('fieldMinRefresh'), type: 'number' },
      { name: 'allowRaw', label: this.text('fieldAllowRaw'), type: 'boolean' },
    ];
  }

  protected override toDialogData(count: number): BulkEditDialogData<ObservedEmbed> {
    return {
      title: this.text('dialogTitle'),
      count,
      singular: this.text('selectedSingular'),
      plural: this.text('selectedPlural'),
      confirm: this.text('confirm'),
      cancel: this.text('cancel'),
      fields: this.bulkFields(),
    };
  }
}
